INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann eine KG nur eine Person haben?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestens zwei Gesellschafter"}, {"text": "Ja", "correct": false, "because": "Komplementär und Kommanditist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine KG ins Handelsregister eingetragen werden?', 2, '[{"text": "Ja", "correct": true, "because": "Rechtliche Anforderung HGB"}, {"text": "Nein", "correct": false, "because": "Pflicht für Handelsgesellschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung in einer KG für alle gleich?', 2, '[{"text": "Nein", "correct": true, "because": "Komplementär voll, Kommanditist begrenzt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Haftungsstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte eine KG in der IT-Branche typisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel für viele Branchen"}, {"text": "Nein", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Ist die Gründung einer KG teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Geringe Mindestkosten"}, {"text": "Ja", "correct": false, "because": "Keine hohen Kapitalanforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Kommanditist in einer KG Entscheidungen treffen?', 2, '[{"text": "Nein", "correct": true, "because": "Komplementär führt Geschäft"}, {"text": "Ja", "correct": false, "because": "Begrenzte Mitbestimmung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Vorteil der KG die begrenzte Haftung für alle?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Kommanditist begrenzt"}, {"text": "Ja", "correct": false, "because": "Komplementär haftet voll"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine KG einen Gesellschaftsvertrag haben?', 2, '[{"text": "Ja", "correct": true, "because": "Gründungsprozess erfordert"}, {"text": "Nein", "correct": false, "because": "Rechtlich notwendig"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil einer KG?', 2, '[{"text": "Begrenzte Haftung für Kommanditisten", "correct": true, "because": "Risikoabsicherung"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Nachteil"}, {"text": "Komplexe Struktur", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin will eine KG gründen. Was ist ein Nachteil?', 3, '[{"text": "Volle Haftung des Komplementärs", "correct": true, "because": "Risiko"}, {"text": "Einfache Gründung", "correct": false, "because": "Vorteil"}, {"text": "Wenig Papierkram", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche ist für eine KG typisch?', 2, '[{"text": "Handel", "correct": true, "because": "Häufige Nutzung"}, {"text": "Nur IT", "correct": false, "because": "Zu spezifisch"}, {"text": "Nur Kunst", "correct": false, "because": "Unüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt nach der Haftung in einer KG. Was sage ich?', 3, '[{"text": "Komplementär voll, Kommanditist begrenzt", "correct": true, "because": "Haftungsstruktur"}, {"text": "Alle voll haftbar", "correct": false, "because": "Falsch"}, {"text": "Niemand haftet", "correct": false, "because": "Unrealistisch"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine KG?', 4, '[{"text": "Begrenzte Haftung für Kommanditisten", "correct": true, "because": "Risikobegrenzung"}, {"text": "Einfache Kapitalbeschaffung", "correct": true, "because": "Kommanditisten einbinden"}, {"text": "Flexible Struktur", "correct": true, "because": "Anpassungsfähig"}, {"text": "Hohe Steuerlast", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sind Nachteile einer KG?', 3, '[{"text": "Volle Haftung des Komplementärs", "correct": true, "because": "Risiko"}, {"text": "Abhängigkeit vom Komplementär", "correct": true, "because": "Führung"}, {"text": "Komplexe Buchführung", "correct": true, "because": "Handelsrecht"}, {"text": "Wenig Papierkram", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gibt es für eine KG?', 3, '[{"text": "Eintrag ins Handelsregister", "correct": true, "because": "HGB"}, {"text": "Gesellschaftsvertrag", "correct": true, "because": "Gründung"}, {"text": "Mindestens zwei Gesellschafter", "correct": true, "because": "Struktur"}, {"text": "Keine Buchführung", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Gründungsprozess einer KG?', 4, '[{"text": "Gesellschaftsvertrag erstellen", "correct": true, "because": "Rechtliche Basis"}, {"text": "Handelsregistereintrag", "correct": true, "because": "Pflicht"}, {"text": "Komplementär und Kommanditist bestimmen", "correct": true, "because": "Struktur"}, {"text": "Urlaub planen", "correct": false, "because": "Kein Bezug"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine KG braucht zwei Gesellschafter. b) Alle haften gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwei ja, Haftung unterschiedlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die KG muss ins Handelsregister. b) Gründung ist teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Register ja, Kosten gering"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kommanditisten haften begrenzt. b) KG ist nur für IT geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, Branche nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Vorteil ist die Kapitalbeschaffung. b) Der Komplementär hat keine Haftung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapital ja, Haftung voll"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

